// OnButtonClicked connects f to the buttonClicked signal. The connection ends when the
// sender is destroyed or Disconnect is called; until then the sender is pinned.
//
//	C++: void QMessageBox::buttonClicked(QAbstractButton * button) [signal]
//
// Qt docs: https://doc.qt.io/qt-6/qmessagebox.html#buttonClicked
func (this *QMessageBox) OnButtonClicked(f func(button *QAbstractButton)) qtcore.Connection {
	self := rt.Use(unsafe.Pointer(this), "QMessageBox.OnButtonClicked")
	id := rt.NewCallback(rt.RefOf(unsafe.Pointer(this)).H, func(args unsafe.Pointer) {
		a := unsafe.Slice((*unsafe.Pointer)(args), 1)
		button := rt.View[QAbstractButton](rt.WrapClass(*(*unsafe.Pointer)(a[0]), "QAbstractButton", rt.KeepOrBorrow), *(*unsafe.Pointer)(a[0]))
		f(button)
	})
	return rt.NewConnection(C.qute_QMessageBox_buttonClicked(self, C.uintptr_t(id)))
}
